namespace PPlusTracklistEditor.Core.Stages;

/// <summary>Where one icon sits on the stage select screen, in the game's menu units (y up), and its scale.</summary>
public readonly record struct IconSpot(float X, float Y, float Scale);

/// <summary>
/// Where the stage select screen draws each icon of a page, copied from the stock <c>sc_selmap.pac</c> (CHR0
/// <c>MenSelmapPos_TopN__0</c>, frame = stage count + 1, bone <c>posNN</c> = the NN-th stage in page order; the same
/// in stock 3.2.1 and the other builds checked). An icon is <see cref="IconWidth"/> x <see cref="IconHeight"/> units
/// times its scale (model <c>MenSelmapIcon</c>).
/// </summary>
public static class StageSelectSpots
{
